import{_ as t,o,c as n,a2 as a}from"./chunks/framework.BZO4qERu.js";const m=JSON.parse('{"title":"AnythingLLM","description":"Connect AnythingLLM to Tokeness using the Generic OpenAI provider.","frontmatter":{"title":"AnythingLLM","description":"Connect AnythingLLM to Tokeness using the Generic OpenAI provider."},"headers":[],"relativePath":"integrations/anythingllm.md","filePath":"integrations/anythingllm.md","lastUpdated":1783700215000}'),r={name:"integrations/anythingllm.md"};function i(d,e,l,s,h,c){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="anythingllm" tabindex="-1">AnythingLLM <a class="header-anchor" href="#anythingllm" aria-label="Permalink to &quot;AnythingLLM&quot;">​</a></h1><p>AnythingLLM&#39;s <code>OpenAI (Generic)</code> provider is designed for OpenAI-compatible interfaces. Tokeness can be connected this way.</p><h2 id="preparation" tabindex="-1">Preparation <a class="header-anchor" href="#preparation" aria-label="Permalink to &quot;Preparation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Base URL</td><td><code>https://n.tokeness.io/v1</code></td></tr><tr><td>API Key</td><td>A key created in the Tokeness console</td></tr><tr><td>Model</td><td>The full model name copied from the Tokeness model catalog</td></tr></tbody></table><p>AnythingLLM comes in desktop, Docker, and cloud versions. Menu locations may differ, but the configuration fields are essentially the same.</p><h2 id="configure-the-llm-provider" tabindex="-1">Configure the LLM Provider <a class="header-anchor" href="#configure-the-llm-provider" aria-label="Permalink to &quot;Configure the LLM Provider&quot;">​</a></h2><ol><li>Open AnythingLLM.</li><li>Go to Settings.</li><li>Find LLM Preference or Model Provider.</li><li>Select <code>OpenAI (Generic)</code> or <code>Generic OpenAI</code>.</li><li>Set the Base URL to <code>https://n.tokeness.io/v1</code>.</li><li>Enter your Tokeness API key.</li><li>Enter the full model name from the Tokeness model catalog.</li><li>Save.</li></ol><p>Field mapping:</p><table tabindex="0"><thead><tr><th>AnythingLLM field</th><th>Tokeness value</th></tr></thead><tbody><tr><td>LLM Provider</td><td><code>OpenAI (Generic)</code></td></tr><tr><td>Base URL / API Base</td><td><code>https://n.tokeness.io/v1</code></td></tr><tr><td>API Key</td><td>Your Tokeness API key</td></tr><tr><td>Model</td><td>A Tokeness model name</td></tr></tbody></table><h2 id="workspace-models" tabindex="-1">Workspace Models <a class="header-anchor" href="#workspace-models" aria-label="Permalink to &quot;Workspace Models&quot;">​</a></h2><p>AnythingLLM supports per-workspace model settings. After saving the global provider, check whether the current workspace is actually using the model you just configured.</p><p>Recommended order:</p><ol><li>Save the Tokeness provider in global settings first.</li><li>Open the workspace settings.</li><li>Confirm the workspace uses the Tokeness provider.</li><li>Select or enter the Tokeness model name.</li><li>Save and reopen the chat.</li></ol><p>If the global save succeeds but the workspace still uses the old model, check the workspace-level override settings.</p><h2 id="knowledge-base-and-embedding-model" tabindex="-1">Knowledge Base and Embedding Model <a class="header-anchor" href="#knowledge-base-and-embedding-model" aria-label="Permalink to &quot;Knowledge Base and Embedding Model&quot;">​</a></h2><p>AnythingLLM treats chat models and vector models as two separate configuration categories. After connecting a chat model, if you want to upload documents and do Q&amp;A, you also need to configure embedding.</p><p>Recommended order:</p><ol><li>Get standard chat working first.</li><li>Then configure the embedding model.</li><li>Upload a small document and test retrieval.</li><li>Only after that, import a larger knowledge base.</li></ol><p>Do not import a large number of files right away. It makes troubleshooting slow and makes it hard to distinguish chat model issues from vector model issues.</p><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><ol><li>Create a test workspace in AnythingLLM.</li><li>Send &quot;reply with ok only&quot;.</li><li>Open the Tokeness usage logs and confirm a request arrived.</li><li>Upload a small text file.</li><li>Ask a question whose answer can be found directly in the file.</li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Action</th></tr></thead><tbody><tr><td>Chat still uses the old model after saving the provider</td><td>Check whether the workspace overrides the global model</td></tr><tr><td>401</td><td>Check the API key</td></tr><tr><td>404</td><td>The Base URL should be <code>https://n.tokeness.io/v1</code></td></tr><tr><td>model not found</td><td>Copy the full model name from the Tokeness model catalog</td></tr><tr><td>Chat works but document Q&amp;A does not</td><td>Configure the embedding model separately</td></tr><tr><td>Responses are very slow</td><td>Test with a short question first, then check the model, context length, and document size</td></tr></tbody></table><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://docs.anythingllm.com/setup/llm-configuration/cloud/openai-generic" target="_blank" rel="noreferrer">AnythingLLM OpenAI Generic LLM</a></li><li><a href="https://docs.anythingllm.com/configuration" target="_blank" rel="noreferrer">AnythingLLM Configuration</a></li></ul>',25)])])}const g=t(r,[["render",i]]);export{m as __pageData,g as default};
